return $input.all().map((item) => {
  const lista = item.json.data;

  if (!lista) {
    throw new Error(
      'La API no devolvió la propiedad data con la lista de pasajeros'
    );
  }

  if (!lista.chofer_id || !lista.chofer_telefono) {
    throw new Error(
      `La corrida ${lista.corrida_id} no tiene chofer o teléfono`
    );
  }

  const reservas = Array.isArray(lista.reservas)
    ? lista.reservas
    : [];

  const detalleReservas = reservas.length === 0
    ? 'No hay pasajeros registrados para esta corrida.'
    : reservas
        .map((reserva, indice) => {
          const cantidadTexto =
            reserva.cantidad_pasajeros === 1
              ? '1 pasajero'
              : `${reserva.cantidad_pasajeros} pasajeros`;

          const observaciones = reserva.observaciones
            ? `\n   Nota: ${reserva.observaciones}`
            : '';

          return [
            `${indice + 1}. ${reserva.pasajero_nombre}`,
            `   Tel: ${reserva.pasajero_telefono}`,
            `   ${cantidadTexto}`,
            `   ${reserva.parada_origen_nombre} → ${reserva.parada_destino_nombre}`,
            `   Reserva: ${reserva.estado_reserva}`,
            `   Pago: ${reserva.estado_pago}`,
            `   Saldo pendiente: $${reserva.saldo_pendiente}${observaciones}`,
          ].join('\n');
        })
        .join('\n\n');

  const mensaje = [
    '🚌 LISTA DE PASAJEROS',
    '',
    `Corrida: ${lista.corrida_folio}`,
    `Ruta: ${lista.ruta_nombre}`,
    `Salida: ${lista.salida_programada}`,
    `Unidad: ${lista.unidad_codigo}`,
    `Chofer: ${lista.chofer_nombre}`,
    '',
    `Reservas: ${lista.total_reservas}`,
    `Pasajeros registrados: ${lista.total_pasajeros_registrados}`,
    `Ocupación máxima: ${lista.ocupacion_maxima}/${lista.capacidad_pasajeros}`,
    `Disponibles mínimos: ${lista.lugares_disponibles_minimos}`,
    '',
    `Total vendido: $${lista.total_vendido}`,
    `Total cobrado: $${lista.total_cobrado}`,
    `Total por cobrar: $${lista.total_por_cobrar}`,
    '',
    'PASAJEROS',
    detalleReservas,
  ].join('\n');

  return {
    json: {
      corrida_id: lista.corrida_id,
      corrida_folio: lista.corrida_folio,

      chofer_id: lista.chofer_id,
      destinatario_nombre: lista.chofer_nombre,
      destinatario_telefono: lista.chofer_telefono,

      mensaje,

      total_reservas: lista.total_reservas,
      total_pasajeros:
        lista.total_pasajeros_registrados,

      envio_simulado: true,
      generado_en: new Date().toISOString(),
    },
  };
});
